(()=>{if(!('serviceWorker'in navigator))return;const ready=navigator.serviceWorker.register('video-stream-v32.js').then(()=>navigator.serviceWorker.ready).then(()=>navigator.serviceWorker.controller?null:new Promise(resolve=>navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true})));ready.then(()=>{const attach=()=>document.querySelectorAll('source[data-video-src]').forEach(s=>{s.src=s.dataset.videoSrc;delete s.dataset.videoSrc;s.parentElement.load()});attach();new MutationObserver(attach).observe(document.getElementById('detail-panel'),{childList:true,subtree:true})}).catch(console.error);})();
